function testSingleFileOCR() {
  var folderName = "Urdu_Scans";

  // 1. Find Folder
  var folders = DriveApp.getFoldersByName(folderName);
  if (!folders.hasNext()) {
    Logger.log("❌ ERROR: Folder '" + folderName + "' not found!");
    Logger.log("   -> Check if you created the folder.");
    Logger.log("   -> Check for typos or capital letters.");
    return;
  }
  var folder = folders.next();

  // 2. Find ONE Image
  var files = folder.getFiles();
  if (!files.hasNext()) {
    Logger.log("❌ ERROR: No files found in folder '" + folderName + "'");
    return;
  }
  var file = files.next();
  var fileName = file.getName();

  Logger.log("🔎 Found file: " + fileName);
  Logger.log("   -> MimeType: " + file.getMimeType());

  // 3. Try Conversion
  try {
    // PRE-CHECK: Does the 'Drive' service exist?
    if (typeof Drive === 'undefined') {
      throw new Error("Drive API Service is NOT enabled. Click '+' next to Services on the left > Add 'Drive API'.");
    }

    var resource = {
      title: "TEST_DOC_" + fileName,
      mimeType: MimeType.GOOGLE_DOCS
    };

    // ATTEMPT OCR (This requires Drive API v2 enabled)
    var imageBlob = file.getBlob();
    var newFile = Drive.Files.insert(resource, imageBlob, {ocr: true, ocrLanguage: "ur"});

    Logger.log("✅ SUCCESS! Created file: " + newFile.title);
    Logger.log("👉 Go check your Drive folder now.");

  } catch (e) {
    Logger.log("❌ CONVERSION FAILED!");
    Logger.log("   Error Message: " + e.message);

    if (e.message.includes("is not a function")) {
      Logger.log("💡 FIX: You might have selected 'Drive API v3' instead of 'v2'."); 
      Logger.log("   -> Remove 'Drive' from Services.");
      Logger.log("   -> Add it again, but select 'Version 2' in the dropdown.");
    }
  }
}
